unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len)
{
    long delta = (long)target - (long)(addr + 5);

    if (len < 5) {
        return len;  // Not enough space for a call instruction
    }

    *(unsigned char *)insnbuf = 0xE8;  // Opcode for call <rel32>
    *(long *)((unsigned char *)insnbuf + 1) = delta;

    return 5;  // Size of the patched instruction
}

