unsigned patch_call_insn(void *insnbuf, const void *target, u16 tgt_clobbers,
                         unsigned long addr, u16 site_clobbers, unsigned len) {
    long delta;
    unsigned char *buf = insnbuf;

    if (len < 5) {
        return len;
    }

    delta = (long)target - (addr + 5);
    buf[0] = 0xe8;  /* Opcode for near call relative */
    *(long *)&buf[1] = delta;

    return 5;
}
